{"check_build":{"code":"script({title:'Hōrin-ji — Hall of the Nine Rings',description:'A timber Buddhist hondō with an open worship veranda, layered irimoya roof and gilded altar, beside a three-storey pagoda. Stone lanterns mark the approach; deep bracket sets and a nine-ring sōrin finish the skyline.',palette:{wood:'reddish brown',red:'dark red',roof:'black',stone:'light bluish grey',paper:'white'}});
const P=(part,x,y,z,colour,turn=0)=>place({part,at:[x,y,z],colour,turn});
function bracket(x,y,z,turn){return group({at:[x,y,z],turn,ops:[P('3665a',0,0,0,'reddish brown'),P('3023b',0,3,0,'dark tan'),P('3665a',0,4,0,'reddish brown'),P('3710',-1,7,0,'reddish brown')]});}
function lantern(x,z){return [floor({at:[x,0,z],size:[4,4],layers:2,colour:'dark bluish grey',top:'tile'}),column({at:[x+1,2,z+1],diameter:2,height:9,colour:'light bluish grey'}),P('3022',x+1,11,z+1,'light bluish grey'),P('3941',x+1,12,z+1,'trans yellow'),P('3960',x,15,z,'light bluish grey'),P('4589',x+1,17,z+1,'light bluish grey')];}
section('Stone terraces and approach',[
box({at:[-2,0,0],size:[38,8,26],colour:'stone',texture:'masonry',top:'tile'}),floor({at:[-2,8,0],size:[38,26],layers:2,colour:'wood',top:'tile'}),stairs({at:[12,0,-6],width:10,steps:5,rise:2,run:1,dir:'+z',colour:'light bluish grey',top:'tile'}),floor({at:[12,0,-13],size:[10,7],layers:1,colour:'dark bluish grey',top:'tile'}),lantern(5,-10),lantern(25,-10),box({at:[-29,0,7],size:[24,7,24],colour:'stone',texture:'masonry',top:'tile'}),floor({at:[-28,7,8],size:[22,22],layers:2,colour:'wood',top:'tile'}),stairs({at:[-21,0,3],width:8,steps:4,rise:2,dir:'+z',colour:'stone',top:'tile'})]);
const hall=[];
hall.push(room({at:[3,10,5],size:[28,24,16],colour:'white',openings:[{side:'front',at:10,width:8,height:21,fill:'none'},{side:'back',at:11,width:6,y:6,height:12,fill:'none'}]}));
for(const z of [5,20]){for(const x of [3,7,11,23,27,30]){hall.push(box({at:[x,10,z],size:[1,24,1],colour:'wood'}));}for(const y of [13,22,31]) hall.push(box({at:[3,y,z],size:[28,1,1],colour:'wood'}));}
for(const x of [3,30]){for(const z of [8,12,16])hall.push(box({at:[x,10,z],size:[1,24,1],colour:'wood'}));for(const y of [13,22,31])hall.push(box({at:[x,y,5],size:[1,1,16],colour:'wood'}));}
for(const z of [3,23])for(const x of [0,6,12,22,28,34]){hall.push(column({at:[x,10,z],height:21,diameter:1,colour:'wood'}),bracket(x,31,z-1,z===3?0:180));}
for(const x of [0,34])for(const z of [9,16])hall.push(column({at:[x,10,z],height:21,colour:'wood'}),bracket(x,31,z,90));
hall.push(floor({at:[-1,39,1],size:[36,24],colour:'wood'}));
for(const z of [1,24])for(let x=0;x<35;x+=2)hall.push(P('3062b',x,36,z,'dark tan'));
for(const z of [1,24])for(const x of [0,4,8,24,28,32])hall.push(P('3633',x,10,z,'reddish brown'));
for(const x of [-1,35])for(const z of [3,7,11,15,19])hall.push(P('3633',x,10,z,'reddish brown',90));
hall.push(box({at:[13,10,15],size:[8,3,4],colour:'dark red',top:'tile'}),box({at:[15,13,16],size:[4,3,2],colour:'pearl gold'}),P('90398',16,16,16,'pearl gold'));
for(const x of [13,20])hall.push(column({at:[x,13,15],height:3,colour:'pearl gold'}),P('6141',x,16,15,'trans yellow'));
hall.push(box({at:[14,10,2],size:[6,4,2],colour:'wood'}));for(let x=14;x<20;x+=2)hall.push(P('2412b',x,14,2,'black'));
section('Hondo timberwork and altar',hall);
const roofs=[roof({style:'hip',at:[-1,40,1],size:[36,24],colour:'black',holes:[{at:[5,7],size:[24,12]}]}),room({at:[5,34,7],size:[24,19,12],colour:'white'}),roof({style:'gable',at:[5,53,7],size:[24,12],colour:'black',gable:'reddish brown',overhang:0,ends:0,ridge:'x'})];
for(const z of [7,18]){for(let x=5;x<29;x+=3)roofs.push(box({at:[x,43,z],size:[1,10,1],colour:'wood'}));for(const y of [44,51])roofs.push(box({at:[5,y,z],size:[24,1,1],colour:'wood'}));}
for(const x of [4,29]){roofs.push(box({at:[x,65,12],size:[1,6,2],colour:'black'}),P('13547',x,71,11,'black'));}
for(const x of [-2,34])for(const z of [0,23])roofs.push(P('13547',x,40,z,'black',z===0?0:180));
section('Layered irimoya roof',roofs);
const pag=[];const cx=-17,cz=19;
function tier(i){const w=14-2*i,r=22-4*i,y=9+30*i,x=cx-w/2,z=cz-w/2,rx=cx-r/2,rz=cz-r/2;const ops=[floor({at:[x-1,y,z-1],size:[w+2,w+2],colour:'wood',top:'tile'}),room({at:[x,y+1,z],size:[w,17,w],colour:'white',openings:i===0?[{side:'front',at:5,width:4,height:15,fill:'none'}]:[]}),floor({at:[rx,y+20,rz],size:[r,r],colour:'wood'}),roof({style:'hip',at:[rx,y+21,rz],size:[r,r],colour:'black',holes:[{at:i<2?[cx-(w-2)/2,cz-(w-2)/2]:[cx-1,cz-1],size:i<2?[w-2,w-2]:[2,2]}]})];
for(const zz of [z,z+w-1]){for(let xx=x;xx<x+w;xx+=3)ops.push(box({at:[xx,y+1,zz],size:[1,17,1],colour:'dark red'}));for(const yy of [y+5,y+13])ops.push(box({at:[x,yy,zz],size:[w,1,1],colour:'wood'}));}
for(const xx of [x,x+w-1])for(let zz=z+3;zz<z+w-1;zz+=3)ops.push(box({at:[xx,y+1,zz],size:[1,17,1],colour:'dark red'}));
for(const zz of [z-1,z+w])for(let xx=x;xx<x+w;xx+=3)ops.push(bracket(xx,y+12,zz,zz===z-1?0:180));
for(const xx of [rx-1,rx+r-1])for(const zz of [rz-1,rz+r-3])ops.push(P('13547',xx,y+21,zz,'black',zz===rz-1?0:180));
if(i<2)ops.push(room({at:[cx-(w-2)/2,y+18,cz-(w-2)/2],size:[w-2,13,w-2],colour:'dark red'}));
return ops;}
for(let i=0;i<3;i++)pag.push(tier(i));
pag.push(column({at:[cx-1,87,cz-1],diameter:2,height:27,colour:'black'}));
for(let i=0;i<9;i++)pag.push(P('4032b',cx-1,114+i*2,cz-1,'pearl gold'),P('3941',cx-1,115+i*2,cz-1,'black'));
pag.push(P('3942c',cx-1,134,cz-1,'pearl gold'));
section('Three storey pagoda and nine ring sorin',pag);","seed":1}}

